INSERT INTO site_settings (id, org_name_ar, org_name_en, tagline_ar, tagline_en, footer_blurb_ar, footer_blurb_en, rights_line_ar, rights_line_en, phone, email, address_ar, address_en, facebook_url, instagram_url, x_url, en_enabled, seo_title_ar, seo_title_en, seo_description_ar, seo_description_en, notify_email_on_status_change, notify_sms_on_status_change, application_ref_prefix, updated_by) VALUES
  (1, 'جمعية سفير الدعوية', 'Safeer Da\'wah Association', 'لطلاب المنح', 'For scholarship students', 'جمعية أهلية غير ربحية متخصصة في رعاية طلاب وطالبات المنح الدوليين الدارسين في الجامعات السعودية.', 'A Saudi non-profit association dedicated to supporting international scholarship students at Saudi universities.', 'جميع الحقوق محفوظة لجمعية سفير بالمملكة العربية السعودية', 'All rights reserved — Safeer Association, Saudi Arabia', '+966 53 464 6648', 'info@safeer-sa.org', 'الرياض — حي السويدي، شارع سدير، المملكة العربية السعودية', 'Riyadh — Al Suwaidi, Sudair St., Kingdom of Saudi Arabia', NULL, NULL, NULL, 1, 'جمعية سفير الدعوية', 'Safeer Da\'wah Association', 'جمعية أهلية غير ربحية متخصصة في رعاية طلاب وطالبات المنح الدوليين الدارسين في الجامعات السعودية.', 'A Saudi non-profit association dedicated to supporting international scholarship students at Saudi universities.', 1, 1, 'SA', NULL);
INSERT INTO pages (slug, title_ar, title_en, meta_title_ar, meta_title_en, meta_description_ar, meta_description_en, is_published, needs_review) VALUES
  ('home', 'الرئيسية', 'Home', 'الرئيسية', 'Home', 'جمعية أهلية غير ربحية متخصصة في رعاية طلاب وطالبات المنح الدوليين الدارسين في الجامعات السعودية.', 'A Saudi non-profit association dedicated to supporting international scholarship students at Saudi universities.', 1, 0),
  ('about', 'من نحن', 'About us', 'من نحن', 'About us', 'جمعية أهلية غير ربحية متخصصة في رعاية طلاب وطالبات المنح الدوليين الدارسين في الجامعات السعودية.', 'A Saudi non-profit association dedicated to supporting international scholarship students at Saudi universities.', 1, 0),
  ('board', 'مجلس الإدارة', 'Board of directors', 'مجلس الإدارة', 'Board of directors', 'المجلس المسؤول عن حوكمة الجمعية واعتماد خططها وبرامجها.', 'The body responsible for governance and for approving the association\'s plans and programmes.', 1, 0),
  ('work', 'مجالات عمل الجمعية', 'Our areas of work', 'مجالات عمل الجمعية', 'Our areas of work', 'تهدف الجمعية إلى نشر التعاليم الإسلامية وتعزيز القيم الدينية، وتعمل في أربعة مجالات رئيسية.', 'The association works to share Islamic teachings and strengthen religious values across four main areas.', 1, 0),
  ('scholarships', 'منح الوافدين للدراسة بالجامعات السعودية', 'Scholarships for international students in Saudi universities', 'منح الوافدين للدراسة بالجامعات السعودية', 'Scholarships for international students in Saudi universities', 'تلعب الجمعية دوراً محورياً في رعاية طلاب المنح الدوليين، عبر دعم شامل يسهّل تكيّفهم ويعزّز تجربتهم الأكاديمية والثقافية.', 'The association plays a central role in caring for international scholarship students, with support that eases adaptation and enriches their academic and cultural experience.', 1, 0),
  ('news', 'أخبار الجمعية', 'Association news', 'أخبار الجمعية', 'Association news', 'أنشطة وفعاليات ومحاضر اجتماعات — بتصنيفات عربية تخص عمل الجمعية.', 'Activities, events and meeting minutes — with categories that match the association\'s actual work.', 1, 0),
  ('article', 'مقال إخباري', 'News article', 'مقال إخباري', 'News article', NULL, NULL, 1, 0),
  ('testimonials', 'قالوا عنا', 'What people say', 'قالوا عنا', 'What people say', 'آراء المستفيدين كما وصلتنا — الإيجابي منها والمقترحات على حد سواء.', 'Beneficiary feedback as we received it — the praise and the suggestions alike.', 1, 0),
  ('partners', 'شركاء النجاح', 'Our partners', 'شركاء النجاح', 'Our partners', 'الجهات التي نعمل معها في رعاية طلاب المنح وتنفيذ البرامج الدعوية والتدريبية.', 'The organisations we work with on student care, outreach and training.', 1, 0),
  ('documents', 'التراخيص والسياسات واللوائح', 'Licences, policies and regulations', 'التراخيص والسياسات واللوائح', 'Licences, policies and regulations', 'مستندات الجمعية الرسمية في مكان واحد — بمعاينة مباشرة وتحميل.', 'Official documents in one place — with previews and downloads.', 1, 0),
  ('contact', 'تواصل معنا', 'Contact us', 'تواصل معنا', 'Contact us', 'إذا كانت لديك أي أسئلة أو كنت بحاجة إلى مساعدة، فلا تتردد في الاتصال بنا.', 'If you have a question or need help, get in touch.', 1, 0);
INSERT INTO page_sections (page_id, section_key, label_ar, label_en, heading_ar, heading_en, body_ar, body_en, primary_button_label_ar, primary_button_label_en, primary_button_url, secondary_button_label_ar, secondary_button_label_en, secondary_button_url, image_asset_id, is_published, sort_order) VALUES
  ((SELECT id FROM pages WHERE slug = 'home'), 'hero', 'الواجهة الرئيسية', 'Hero', 'نرعى طلاب المنح ونبني جسور المعرفة', 'We care for scholarship students and build bridges', 'دعم أكاديمي ونفسي وإرشاد ديني وتمكين مجتمعي لطلاب وطالبات المنح الدوليين الدارسين في الجامعات السعودية.', 'Academic and psychological support, religious guidance and community empowerment for international scholarship students at Saudi universities.', 'قدّم طلب منحة', 'Apply for a scholarship', '#/apply', 'تعرّف على الجمعية', 'About the association', '#/about', NULL, 1, 0),
  ((SELECT id FROM pages WHERE slug = 'home'), 'about', 'من نحن', 'About', 'الرؤية والرسالة والأهداف', 'Vision, mission and goals', NULL, NULL, 'اقرأ المزيد عن الجمعية', 'Read more about us', '#/about', NULL, NULL, NULL, NULL, 1, 1),
  ((SELECT id FROM pages WHERE slug = 'home'), 'impact', 'أثرنا', 'Our impact', 'بالأرقام', 'In numbers', 'تُحرَّر هذه الأرقام من لوحة التحكم — ولا تُنشر إلا بأرقام موثقة.', 'Edited from the dashboard — published only once verified.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 2),
  ((SELECT id FROM pages WHERE slug = 'home'), 'work_areas', 'مجالات عملنا', 'Our work', 'أربعة مجالات، هدف واحد', 'Four areas, one purpose', NULL, NULL, NULL, NULL, NULL, 'كل المجالات', 'All areas', '#/work', NULL, 1, 3),
  ((SELECT id FROM pages WHERE slug = 'home'), 'student_care', 'منح الوافدين', 'Scholarships', 'رعاية متكاملة لطالب المنحة', 'Complete care for a scholarship student', 'من لحظة الوصول إلى التخرج: دعم يسهّل التكيّف مع البيئة الجديدة ويعزّز التجربة الأكاديمية والثقافية.', 'From arrival to graduation: support that eases adaptation and strengthens the academic and cultural experience.', 'تفاصيل برنامج المنح', 'Scholarship programme details', '#/scholarships', NULL, NULL, NULL, NULL, 1, 4),
  ((SELECT id FROM pages WHERE slug = 'home'), 'news', 'أخبارنا', 'News', 'آخر الأنشطة', 'Latest activity', NULL, NULL, NULL, NULL, NULL, 'كل الأخبار', 'All news', '#/news', NULL, 1, 5),
  ((SELECT id FROM pages WHERE slug = 'home'), 'testimonials', 'قالوا عنا', 'Testimonials', 'ما يقوله المستفيدون', 'What beneficiaries say', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 6),
  ((SELECT id FROM pages WHERE slug = 'home'), 'partners', 'شركاء النجاح', 'Partners', 'من نعمل معهم', 'Who we work with', NULL, NULL, NULL, NULL, NULL, 'مشاهدة كل الشركاء', 'See all partners', '#/partners', NULL, 0, 7),
  ((SELECT id FROM pages WHERE slug = 'home'), 'cta', 'دعوة للتسجيل', 'Call to action', 'للتسجيل في جمعية سفير الدعوية', 'Register with Safeer Association', 'قدّم طلبك إلكترونياً وتابع حالته من بوابة الطالب دون مراجعة المقر.', 'Apply online and follow your application in the student portal — no office visit needed.', 'تسجيل طلب منحة', 'Apply now', '#/apply', 'تواصل معنا', 'Contact us', '#/contact', NULL, 1, 8);
INSERT INTO about_items (kind, icon, title_ar, title_en, body_ar, body_en, is_published, sort_order) VALUES
  ('vision', 'eye', 'الرؤية', 'Vision', 'الريادة في الدعوة المتخصصة باستخدام التقنية الحديثة، ورعاية طلاب المنح في الجامعات السعودية.', 'Leadership in specialised outreach using modern technology, and care for scholarship students at Saudi universities.', 1, 0),
  ('mission', 'msg', 'الرسالة', 'Mission', 'تقديم خدمات دعوية وتعليمية وإرشادية نوعية تُعرّف بالإسلام، وتدعم الطالب الوافد أكاديمياً ونفسياً ومجتمعياً.', 'Delivering quality outreach, education and guidance that introduce Islam and support incoming students academically, psychologically and socially.', 1, 0),
  ('goal', NULL, 'استخدام التقنية الحديثة في الدعوة إلى الله ونشر العلم الشرعي', 'Using modern technology in outreach and in spreading religious knowledge', NULL, NULL, 1, 0),
  ('goal', NULL, 'تصحيح المفاهيم المغلوطة عن الإسلام ورد الشبهات المثارة عليه', 'Correcting misconceptions about Islam and answering claims raised against it', NULL, NULL, 1, 1),
  ('goal', NULL, 'تعليم المسلمين أصول دينهم وتعميق روابط الأخوة فيما بينهم', 'Teaching Muslims the fundamentals of their faith and deepening bonds between them', NULL, NULL, 1, 2),
  ('goal', NULL, 'الدعوة المتخصصة للفئات الاجتماعية', 'Specialised outreach for specific social groups', NULL, NULL, 1, 3),
  ('goal', NULL, 'الاهتمام الدعوي بالجاليات والتواصل معهم', 'Engaging with and supporting expatriate communities', NULL, NULL, 1, 4),
  ('care_pillar', 'book', 'الدعم الأكاديمي والتعليمي', 'Academic and educational support', 'دورات تعليم اللغة العربية لغير الناطقين بها، ودروس تقوية في المواد الأكاديمية، ومرشدون أكاديميون للمناهج والبحوث والمشاريع.', 'Arabic courses for non-native speakers, tutoring in academic subjects, and academic mentors for curricula, research and projects.', 1, 0),
  ('care_pillar', 'heart', 'الدعم النفسي والإرشادي', 'Psychological and counselling support', 'مستشارون متخصصون، وجلسات توعية وورش عمل حول مهارات التكيّف وإدارة الضغوط بعيداً عن الأهل والوطن.', 'Specialist counsellors, awareness sessions and workshops on adapting and managing pressure far from home.', 1, 1),
  ('care_pillar', 'mosque', 'الإرشاد الديني والدعوي', 'Religious guidance', 'دروس في الفقه والشريعة، ولقاءات دعوية، وتيسير أداء الفرائض وتنظيم رحلات العمرة والزيارة.', 'Classes in jurisprudence and Shari\'ah, outreach gatherings, prayer facilities and organised Umrah trips.', 1, 2),
  ('care_pillar', 'people', 'التمكين والمشاركة المجتمعية', 'Empowerment and community participation', 'تشجيع الطلاب على الأنشطة التطوعية وخدمة المجتمع السعودي، بما يعزّز شعور الانتماء والاندماج.', 'Encouraging students into volunteering and service to Saudi society, strengthening belonging and integration.', 1, 3),
  ('scholarship_step', NULL, 'تعبئة الطلب', 'Fill the form', 'بيانات شخصية وأكاديمية عبر نموذج من ثلاث خطوات.', 'Personal and academic details in a three-step form.', 1, 0),
  ('scholarship_step', NULL, 'رفع المستندات', 'Upload documents', 'صورة الهوية والشهادات الدراسية بصيغة PDF أو صورة.', 'ID copy and certificates as PDF or image.', 1, 1),
  ('scholarship_step', NULL, 'المراجعة الأولية', 'Initial review', 'تدقيق اكتمال البيانات والمستندات من فريق الجمعية.', 'The team checks the data and documents are complete.', 1, 2),
  ('scholarship_step', NULL, 'المقابلة', 'Interview', 'موعد يُحجز من البوابة عند اجتياز المراجعة.', 'Booked from the portal once review is passed.', 1, 3),
  ('scholarship_step', NULL, 'القرار والرعاية', 'Decision and care', 'إشعار بالقرار، ثم بدء برنامج الرعاية والمتابعة.', 'Decision notice, then the care programme begins.', 1, 4),
  ('requirement', NULL, 'صورة الهوية أو جواز السفر', 'ID or passport copy', NULL, NULL, 1, 0),
  ('requirement', NULL, 'الشهادات الدراسية', 'Academic certificates', NULL, NULL, 1, 1),
  ('requirement', NULL, 'اسم الجامعة والمرحلة الدراسية', 'University name and degree level', NULL, NULL, 1, 2),
  ('requirement', NULL, 'بريد إلكتروني ورقم هاتف فعّالان', 'A working email and phone number', NULL, NULL, 1, 3);
