INSERT INTO posts (slug, title_ar, title_en, excerpt_ar, excerpt_en, body_ar, body_en, category_id, cover_asset_id, published_on, is_featured, is_legacy, is_published, created_by) VALUES
  ('safeer-dates-distribution-2020', 'توزيع ٥٠٠ كرتونة تمور مقدمة من جمعية سفير', 'Distributing 500 boxes of dates donated by Safeer Association', 'ضمن المشاركات المجتمعية للجمعية، وُزّعت الكراتين على المستفيدين بالتعاون مع الجهات الشريكة.', 'As part of the association\'s community work, the boxes were distributed to beneficiaries with partner organisations.', NULL, NULL, (SELECT id FROM news_categories WHERE slug = 'community'), NULL, '2020-07-30', 1, 0, 1, NULL);
INSERT INTO testimonial_themes (title_ar, title_en, description_ar, description_en, is_improvement, sort_order) VALUES
  ('تجربة تعليمية ممتازة', 'An excellent learning experience', 'امتنان للدروس والمحاضرات التي تقدّمها الجمعية، وإشادة بأسلوب التعليم الشامل والميسّر.', 'Gratitude for the association\'s classes and lectures, and praise for its clear, accessible teaching.', 0, 0),
  ('دعم شخصي', 'Personal support', 'دعم فردي في فهم الإسلام أو في تبنّيه كدين جديد.', 'One-to-one support in understanding Islam or in embracing it as a new faith.', 0, 1),
  ('بيئة مرحبة', 'A welcoming environment', 'بيئة دافئة تُشعر المستفيد بالراحة والانتماء.', 'A warm environment where people feel comfortable and that they belong.', 0, 2),
  ('تنظيم الفعاليات', 'Event organisation', 'تقدير للأنشطة مع اقتراحات بتحسين التنظيم والتواصل.', 'Appreciation for the activities, with suggestions to improve organisation and communication.', 1, 3),
  ('موارد إضافية', 'More resources', 'اقتراحات بزيادة الموارد التعليمية من كتب ومقالات.', 'Suggestions to expand educational resources such as books and articles.', 1, 4);
INSERT INTO testimonials (quote_ar, quote_en, author_name, author_desc_ar, author_desc_en, status, is_featured, source, source_message_id, sort_order) VALUES
