INSERT INTO mail_templates (`key`, name_ar, name_en, subject_ar, subject_en, body_ar, body_en, variables, is_enabled, updated_by) VALUES
  ('contact_ack', 'تأكيد استلام رسالة التواصل', 'Contact acknowledgement', 'شكرًا لتواصلك مع جمعية سفير الدعوية', 'Thank you for contacting Safeer Association', 'مرحبًا {{name}}،\n\nشكرًا لتواصلك مع جمعية سفير الدعوية. وصلتنا رسالتك وسيتواصل معك أحد أعضاء الفريق في أقرب وقت ممكن.\n\nمع تحياتنا،\nفريق جمعية سفير', 'Hello {{name}},\n\nThank you for contacting Safeer Da\'wah Association. We have received your message, and a member of our team will get back to you as soon as possible.\n\nWith appreciation,\nThe Safeer Association Team', '[\"name\"]', 1, NULL),
  ('contact_notify', 'إشعار رسالة تواصل جديدة', 'New contact message notification', 'رسالة تواصل جديدة من {{name}}', 'New contact message from {{name}}', 'وصلت رسالة تواصل جديدة عبر الموقع.\n\n**الاسم:** {{name}}\n**البريد الإلكتروني:** {{email}}\n**الهاتف:** {{phone}}\n**الموضوع:** {{subject}}\n\n**نص الرسالة:**\n{{message}}\n\nيمكنك عرض الرسالة والرد عليها من لوحة التحكم: [{{link}}]({{link}})', 'A new contact message has arrived through the website.\n\n**Name:** {{name}}\n**Email:** {{email}}\n**Phone:** {{phone}}\n**Subject:** {{subject}}\n\n**Message:**\n{{message}}\n\nView and reply to it from the dashboard: [{{link}}]({{link}})', '[\"name\",\"email\",\"phone\",\"subject\",\"message\",\"link\"]', 1, NULL),
  ('user_invite', 'دعوة مستخدم جديد', 'User invitation', 'دعوة للانضمام إلى لوحة تحكم جمعية سفير', 'You\'re invited to the Safeer Association dashboard', 'مرحبًا {{name}}،\n\nدعاك {{inviter}} للانضمام إلى فريق لوحة تحكم جمعية سفير الدعوية بصلاحية {{role}}. لإنشاء كلمة مرورك وتفعيل حسابك، يرجى الضغط على الرابط التالي خلال 48 ساعة:\n\n[{{link}}]({{link}})\n\nإذا لم تكن تتوقع هذه الدعوة، يمكنك تجاهل هذه الرسالة بأمان.', 'Hello {{name}},\n\n{{inviter}} has invited you to join the Safeer Association dashboard team with {{role}} access. To set your password and activate your account, please follow this link within 48 hours:\n\n[{{link}}]({{link}})\n\nIf you weren\'t expecting this invitation, you can safely ignore this message.', '[\"name\",\"inviter\",\"role\",\"link\"]', 1, NULL),
  ('password_reset', 'إعادة تعيين كلمة المرور', 'Password reset', 'إعادة تعيين كلمة المرور', 'Reset your password', 'مرحبًا {{name}}،\n\nتلقينا طلبًا لإعادة تعيين كلمة المرور الخاصة بحسابك في لوحة تحكم جمعية سفير. يرجى الضغط على الرابط التالي خلال 60 دقيقة لتعيين كلمة مرور جديدة:\n\n[{{link}}]({{link}})\n\nإذا لم تطلب ذلك، تجاهل هذه الرسالة ولن يتغير شيء في حسابك.', 'Hello {{name}},\n\nWe received a request to reset the password for your Safeer Association dashboard account. Please follow this link within 60 minutes to set a new password:\n\n[{{link}}]({{link}})\n\nIf you didn\'t request this, you can safely ignore this message and nothing will change.', '[\"name\",\"link\"]', 1, NULL),
  ('application_started', 'بدء طلب منحة', 'Scholarship application started', 'بدأت طلب منحة برقم {{reference}}', 'You started a scholarship application — {{reference}}', 'مرحبًا {{name}}،\n\nبدأت تسجيل طلب منحة في جمعية سفير الدعوية، ورقم طلبك هو **{{reference}}**. يُحفَظ تقدّمك تلقائيًا، ويمكنك العودة لإكمال بقية الخطوات من بوابة الطالب في أي وقت:\n\n[{{link}}]({{link}})\n\nإن لم تُكمل الطلب الآن، يمكنك العودة إليه لاحقًا باستخدام رقم الطلب أو بريدك الإلكتروني.', 'Hello {{name}},\n\nYou started a scholarship application with Safeer Association. Your application reference is **{{reference}}**. Your progress is saved automatically, and you can return to finish the remaining steps from the student portal at any time:\n\n[{{link}}]({{link}})\n\nIf you don\'t finish now, you can come back later using your reference or email.', '[\"name\",\"reference\",\"link\"]', 1, NULL),
  ('application_submitted', 'إرسال طلب المنحة', 'Scholarship application submitted', 'استلمنا طلبك رقم {{reference}}', 'We received your application — {{reference}}', 'مرحبًا {{name}}،\n\nاستلمنا طلب المنحة الخاص بك برقم **{{reference}}**، وسيبدأ فريق الجمعية بمراجعة بياناتك ومستنداتك قريبًا. يمكنك متابعة حالة الطلب في أي وقت من بوابة الطالب:\n\n[{{link}}]({{link}})\n\nسنُعلمك بالبريد الإلكتروني والرسائل النصية عند أي تحديث.', 'Hello {{name}},\n\nWe have received your scholarship application, reference **{{reference}}**. Our team will begin reviewing your details and documents shortly. You can follow its status at any time from the student portal:\n\n[{{link}}]({{link}})\n\nWe will notify you by email and SMS with any update.', '[\"name\",\"reference\",\"link\"]', 1, NULL),
  ('application_status_changed', 'تحديث حالة الطلب', 'Application status update', 'تحديث على طلبك {{reference}}: {{status}}', 'Update on your application {{reference}}: {{status}}', 'مرحبًا {{name}}،\n\nتحدّثت حالة طلبك رقم **{{reference}}** إلى: **{{status}}**.\n\n{{note}}\n\nيمكنك مراجعة التفاصيل كاملة من بوابة الطالب:\n\n[{{link}}]({{link}})', 'Hello {{name}},\n\nThe status of your application **{{reference}}** has changed to: **{{status}}**.\n\n{{note}}\n\nYou can review the full details from the student portal:\n\n[{{link}}]({{link}})', '[\"name\",\"reference\",\"status\",\"note\",\"link\"]', 1, NULL),
  ('document_rejected', 'رفض مستند مرفوع', 'Uploaded document rejected', 'مطلوب إجراء: مستند في طلبك {{reference}} يحتاج إعادة رفع', 'Action needed: a document in {{reference}} needs re-upload', 'مرحبًا {{name}}،\n\nراجع فريق الجمعية مستند **{{docType}}** ضمن طلبك رقم **{{reference}}**، ولم يُقبل للسبب التالي:\n\n> {{reason}}\n\nيرجى إعادة رفع نسخة أوضح من بوابة الطالب لاستكمال المراجعة:\n\n[{{link}}]({{link}})', 'Hello {{name}},\n\nOur team reviewed the **{{docType}}** document in your application **{{reference}}**, and it was not accepted for the following reason:\n\n> {{reason}}\n\nPlease re-upload a clearer copy from the student portal so the review can continue:\n\n[{{link}}]({{link}})', '[\"name\",\"reference\",\"docType\",\"reason\",\"link\"]', 1, NULL),
  ('documents_requested', 'طلب استكمال مستندات', 'Documents requested', 'مطلوب استكمال مستندات لطلبك {{reference}}', 'Documents needed for your application {{reference}}', 'مرحبًا {{name}}،\n\nلاستكمال مراجعة طلبك رقم **{{reference}}**، نحتاج منك رفع أو استبدال المستندات التالية:\n\n{{docTypes}}\n\n{{message}}\n\nيمكنك رفعها من بوابة الطالب:\n\n[{{link}}]({{link}})', 'Hello {{name}},\n\nTo continue reviewing your application **{{reference}}**, please upload or replace the following documents:\n\n{{docTypes}}\n\n{{message}}\n\nYou can upload them from the student portal:\n\n[{{link}}]({{link}})', '[\"name\",\"reference\",\"docTypes\",\"message\",\"link\"]', 1, NULL),
  ('message_reply', 'رد على رسالة تواصل', 'Reply to your message', 'رد جمعية سفير على رسالتك', 'Safeer Association replied to your message', 'مرحبًا {{name}}،\n\n{{message}}\n\n—\nفريق جمعية سفير الدعوية', 'Hello {{name}},\n\n{{message}}\n\n—\nThe Safeer Da\'wah Association Team', '[\"name\",\"message\"]', 1, NULL),
  ('otp_code', 'رمز التحقق لمرة واحدة', 'One-time verification code', 'رمز الدخول إلى بوابة الطالب: {{code}}', 'Your student portal sign-in code: {{code}}', 'رمز الدخول إلى بوابة الطالب هو: **{{code}}**\n\nصالح لمدة {{minutes}} دقائق. لا تشارك هذا الرمز مع أحد.\n\nإذا لم تطلب هذا الرمز، تجاهل هذه الرسالة.', 'Your student portal sign-in code is: **{{code}}**\n\nIt is valid for {{minutes}} minutes. Do not share this code with anyone.\n\nIf you did not request it, you can ignore this message.', '[\"code\",\"minutes\"]', 1, NULL);
INSERT INTO sms_templates (`key`, name_ar, name_en, body_ar, body_en, variables, is_enabled, updated_by) VALUES
  ('otp_code', 'رمز التحقق', 'Verification code', 'رمز الدخول إلى بوابة سفير: {{code}} (صالح {{minutes}} دقائق)', 'Your Safeer portal code: {{code}} (valid {{minutes}} min)', '[\"code\",\"minutes\"]', 1, NULL),
  ('application_submitted', 'إرسال الطلب', 'Application submitted', 'جمعية سفير: استلمنا طلبك {{reference}}. تابع حالته عبر بوابة الطالب.', 'Safeer: we received your application {{reference}}. Track it in the student portal.', '[\"reference\"]', 1, NULL),
  ('application_status_changed', 'تحديث الحالة', 'Status update', 'جمعية سفير: تحدّثت حالة طلبك {{reference}} إلى {{status}}.', 'Safeer: your application {{reference}} status changed to {{status}}.', '[\"reference\",\"status\"]', 1, NULL),
  ('documents_requested', 'طلب مستندات', 'Documents requested', 'جمعية سفير: يلزم استكمال مستندات لطلبك {{reference}}. راجع بوابة الطالب.', 'Safeer: documents are needed for application {{reference}}. Check the student portal.', '[\"reference\"]', 1, NULL);
